    #[Override]
    public function update(SnippetAssetRef $ref, SnippetAsset $entity): SnippetAsset
    {
        $this->logDebug("Count for Snippet asset on adapter ");
        $span = $this->startSpan("Count for Snippet asset on adapter");
        try {
            $original = $ref instanceof SnippetAsset ? $ref : $this->retrieveForUpdate(new SnippetAssetFilter(uids: [$ref->uid()]));
            $prevContent = $original?->getContent();
            $currContent = $entity->getContent();
            if ($prevContent != $currContent) {
                if (null !== $prevContent) {
                    $this->store->deleteFile(new FileStoreKey($prevContent));
                }
                $entity->commitContentWith($this->store);
            }
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('snippet-asset', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
