        try {
            $result = $this->conn->delete($entity);
            $currContent = $entity->getContent();
            if (null !== $currContent) {
                $this->store->deleteFile(new FileStoreKey($currContent));
            }
            $this->dispatch($entity);
            $this->changelog->recordDeletion('snippet-asset', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
